use vstd::prelude::*;

verus! {

fn reverse(s: Vec<i8>) -> (rev: Vec<i8>)
    ensures
        rev.len() == s.len(),
        forall|i: int| 0 <= i < s.len() ==> rev[i] == s[s.len() - 1 - i],
{
    let n = s.len();
    let mut rev = Vec::with_capacity(n);

    for i in (0..n).rev()
        invariant
            n == s.len(),
            0 <= rev.len() <= n,
            // Elements accumulated so far are exactly the last rev.len() elements of s, in order.
            forall|j: int| 0 <= j < rev.len() ==> rev[j] == s[n - rev.len() + j],
        decreases i,
    {
        rev.push(s[i]);

        // Helpful fact for the verifier: after pushing, the new last element matches s[i].
        assert(rev[rev.len() as int - 1] == s[i as int]);
    }

    rev
}

}

